SELECT toUnixTimestamp(time) AS sample_unix,virtual_table_name,tag_names,tag_values,metrics_float_names,metrics_float_values FROM deepflow_admin.deepflow_server_local WHERE virtual_table_name='deepflow_server_ingester_ckwriter' AND tag_values[indexOf(tag_names,'host')]='f2e9872ccdfd' AND position(tag_values[indexOf(tag_names,'table')],'l7_flow_log')>0 AND time>=toDateTime(1793021362) AND time<=toDateTime(1793021863) ORDER BY time,tag_values FORMAT JSONEachRow
